/* FitFirst prototype — one consultation flow, three packagings: kiosk · assisted (staff tablet) · QR Stylist (shopper's phone) */
(function () {
  const FF = window.FF, t = FF.t, esc = FF.esc, $ = FF.$, E = FF.engine;
  FF.load();
  const q = new URLSearchParams(location.search);
  const MODE = ['kiosk', 'assisted', 'qr'].includes(q.get('mode')) ? q.get('mode') : 'kiosk';
  const store = () => FF.db.stores.find((s) => s.id === FF.db.storeId);
  const flags = () => FF.db.settings.flags;
  const staffer = () => FF.me() || FF.db.staff.find((s) => s.role === 'STAFF');
  const newProfile = (label) => ({ label, dept: null, isMinor: false, cats: [], occasion: null, budget: 0, sizes: {}, height: null, likes: [], dislikes: [], tone: null, undertone: 'unknown', contrast: 'unknown', method: null, goals: [], quiz: {} });
  const fresh = () => ({ step: MODE === 'kiosk' ? 'attract' : 'lang', hist: [], consent: { personal: true, camera: false }, who: 'me', profiles: [newProfile('Me')], pi: 0, visit: null, res: null, toneMode: null, cam: null, returnTo: null, notified: false, rated: 0, left: 90 });
  let K = fresh(), last = Date.now(), idleLeft = 0;
  const P = () => K.profiles[K.pi];
  const ORDER = ['who', 'dept', 'need', 'size', 'colours', 'tone', 'goals', 'results'];
  const applies = (s) => !((s === 'tone' || s === 'goals') && P().isMinor);
  const go = (s, keep) => { if (!keep) K.hist.push(K.step); K.step = s; K.toneMode = s === 'tone' ? null : K.toneMode; stopCam(); render(); window.scrollTo(0, 0); };
  const next = () => { if (K.returnTo) { const r = K.returnTo; K.returnTo = null; return go(r); } const flow = ['lang', 'consent', ...ORDER, 'handoff']; let i = flow.indexOf(K.step) + 1; while (!applies(flow[i])) i++; go(flow[i]); };
  const back = () => { const s = K.hist.pop(); if (s) { K.step = s; K.toneMode = null; stopCam(); render(); } };
  const visit = () => K.visit && FF.db.visits.find((v) => v.code === K.visit);
  const ev = (v, type, text) => v.events.push({ at: Date.now(), type, text });

  /* ---------- shell ---------- */
  function render() {
    document.documentElement.lang = FF.lang;
    const s = STEPS[K.step](); const st = store();
    const idx = ORDER.indexOf(K.step), prog = idx < 0 ? (K.step === 'handoff' ? 100 : 0) : ((idx + 1) / ORDER.length) * 100;
    const head = s.bare ? '' : `<header class="k-head"><div class="k-brand grow">${esc(st.name)}<small>FitFirst · ${MODE === 'assisted' ? 'assisted consultation' : MODE === 'qr' ? 'QR Stylist' : 'in-store stylist'}</small></div>
      ${flags().offline ? `<span class="badge b-warn">${FF.icon('wifioff')} ${t('offline')}</span>` : ''}
      <button class="btn btn-g btn-s" data-act="pop" data-menu="lang" aria-label="Language">${FF.icon('globe')} ${FF.LANGS.find((l) => l[0] === FF.lang)[1]}</button>
      ${MODE !== 'qr' ? `<button class="btn btn-s" data-act="k-help">${FF.icon('help')} ${t('help')}</button>` : ''}
      <button class="btn btn-g btn-s" data-act="k-restart">${t('startover')}</button></header><div class="k-prog"><i style="width:${prog}%"></i></div>`;
    const sb = MODE === 'assisted' ? `<div class="staffbar"><span>${FF.icon('user')}</span><span class="grow">Assisted mode · ${esc(staffer().name)} is guiding this shopper</span><a class="link" style="color:#E8C77A" href="app.html#/queue">Staff app</a></div>` : '';
    const foot = s.foot === false || s.bare ? '' : `<footer class="k-foot">${K.hist.length ? `<button class="btn" data-act="k-back">${FF.icon('left')} ${t('back')}</button>` : ''}<span class="grow"></span>${s.skip ? `<button class="btn btn-g" data-act="k-next">${t('skip')}</button>` : ''}${s.foot || `<button class="btn btn-p" data-act="k-next" ${s.block ? 'disabled' : ''}>${s.contLabel || t('cont')} ${FF.icon('right')}</button>`}</footer>`;
    $('#root').innerHTML = `<div class="k-app ${MODE}">${sb}${head}${s.bare ? s.body : `<main class="k-main">${s.body}</main>`}${foot}</div>
      <div class="demo-pill"><button data-act="pop" data-menu="demo">Demo controls</button></div>`;
    if (s.after) s.after();
  }
  FF.render = render;
  FF.menu('lang', () => FF.LANGS.map((l) => `<button data-act="k-lang" data-v="${l[0]}">${l[1]}${FF.lang === l[0] ? ' ✓' : ''}</button>`).join(''));
  FF.menu('demo', () => { const f = flags(); const row = (k, l) => `<button data-act="k-flag" data-k="${k}">${f[k] ? '☑' : '☐'} ${l}</button>`; return `<div class="pop-text b">Prototype scenarios</div>${row('offline', 'Internet is down')}${row('camDenied', 'Camera permission denied')}${row('lowLight', 'Poor lighting (camera unsure)')}<hr style="margin:4px 0"><button data-act="k-mode" data-v="kiosk">Switch to kiosk mode</button><button data-act="k-mode" data-v="assisted">Switch to assisted mode</button><button data-act="k-mode" data-v="qr">Switch to QR Stylist (phone)</button><button data-act="k-hub">← Back to prototype hub</button>`; });
  FF.act('k-flag', (d) => { flags()[d.k] = !flags()[d.k]; FF.save(); FF.$('.pop')?.remove(); render(); FF.toast('Scenario ' + (flags()[d.k] ? 'on' : 'off'), 'warn'); });
  FF.act('k-mode', (d) => { location.href = 'kiosk.html?mode=' + d.v; });
  FF.act('k-hub', () => { location.href = 'index.html'; });
  FF.act('k-lang', (d) => { FF.lang = d.v; FF.$('.pop')?.remove(); if (K.step === 'lang') next(); else render(); });
  FF.act('k-next', () => next()); FF.act('k-back', () => back());
  FF.act('k-restart', () => { if (K.step === 'lang' || K.step === 'attract') return reset(); FF.confirm(t('startover') + '?', 'Your answers on this screen will be cleared.', t('startover'), () => reset(true)); });
  FF.act('k-help', () => { FF.db.help.unshift({ id: FF.uid('h'), at: Date.now(), where: MODE === 'kiosk' ? 'Entrance kiosk' : 'Counter tablet 1', code: K.visit, done: false }); FF.save(); FF.toast(t('help_sent'), 'ok'); });
  function reset(abandon) { const v = visit(); if (v && v.status === 'BROWSING') { v.status = 'ABANDONED'; ev(v, 'abandoned', 'Left at step “' + K.step + '”'); FF.save(); } clearInterval(K.timer); stopCam(); FF.closeOverlay(); K = fresh(); FF.lang = 'en'; render(); if (abandon) FF.toast('Cleared', ''); }

  /* ---------- steps ---------- */
  const STEPS = {
    attract: () => ({ bare: true, body: `<section class="attract"><div class="rail">${['SR-1001', 'LH-3002', 'KS-2003'].map((id) => `<div>${FF.garment(FF.prod(id))}</div>`).join('')}</div>
      <div><div class="k-brand" style="color:#E8C77A">${esc(store().name)}<small style="color:#B9AE9A">${esc(store().area)} · powered by FitFirst</small></div></div>
      <div style="position:relative;z-index:2"><h1>${t('attract_h')}</h1><p class="lead">${t('attract_s')}</p><div class="row wrap mt24"><button class="btn btn-l" data-act="k-begin">${t('start')} ${FF.icon('right')}</button>${FF.LANGS.filter((l) => l[0] !== 'en').map((l) => `<button class="btn btn-l alt" data-act="k-begin" data-v="${l[0]}">${l[1]}</button>`).join('')}</div></div>
      <div class="row wrap between small" style="color:#B9AE9A"><span>${t('trust')}</span><span class="row gap6">${FF.icon(flags().offline ? 'wifioff' : 'wifi')} ${flags().offline ? 'Offline — using saved stock' : 'Stock updated ' + FF.ago(Date.now() - 180000) + ' ago'}</span></div></section>` }),
    lang: () => ({ foot: false, body: `<div class="k-step">${MODE === 'qr' ? 'Welcome to ' + esc(store().name) : '1 · Language'}</div><h1>${t('lang_h')}</h1><div class="tiles big">${FF.LANGS.map((l) => `<button class="tile" data-act="k-lang" data-v="${l[0]}" style="font-family:var(--serif);font-size:26px;min-height:96px;justify-content:center" aria-pressed="false">${l[1]}</button>`).join('')}</div>${MODE === 'assisted' ? `<p class="note n-plain mt24">Assisted mode: go through the questions <b>with</b> the shopper. Every answer after “section” can be skipped.</p>` : ''}` }),
    consent: () => ({ foot: `<button class="btn btn-g" data-act="k-decline">${t('decline')}</button><button class="btn btn-p" data-act="k-agree" ${K.consent.personal ? '' : 'disabled'}>${t('agree')} ${FF.icon('right')}</button>`,
      body: `<div class="k-step">${FF.icon('shield')}</div><h1>${t('consent_h')}</h1><p class="lead">${t('consent_s')}</p>
      <div class="col mt24" style="max-width:640px">
        <div class="card row top gap16"><div class="grow"><h3>${t('c1_t')}</h3><p class="small muted mt4">${t('c1_d', { days: FF.db.settings.retention.visitDays })}</p></div>${FF.ui.switch('k-consent', K.consent.personal, 'data-k="personal" aria-label="' + esc(t('c1_t')) + '"')}</div>
        ${MODE !== 'qr' ? `<div class="card row top gap16"><div class="grow"><h3>${t('c2_t')}</h3><p class="small muted mt4">${t('c2_d')}</p></div>${FF.ui.switch('k-consent', K.consent.camera, 'data-k="camera" aria-label="' + esc(t('c2_t')) + '"')}</div>` : ''}
        <p class="small muted">${FF.icon('info', 'hide')}${t('c3')}</p><button class="link small" style="align-self:flex-start" data-act="k-notice">${t('notice')}</button></div>` }),
    declined: () => ({ foot: `<button class="btn btn-p" data-act="k-restart">${t('done')}</button>`, body: `<div class="center" style="margin:auto"><h1 style="margin:0 auto">${t('declined_h')}</h1><p class="lead" style="margin:10px auto 0">${t('declined_s')}</p>${MODE !== 'qr' ? `<button class="btn btn-l mt24" data-act="k-help">${FF.icon('help')} ${t('help')}</button>` : ''}</div>` }),
    who: () => ({ body: `<div class="k-step">1 / 7</div><h1>${t('who_h')}</h1><div class="tiles big">${[['me', 'who_me', ''], ['other', 'who_other', 'who_other_d'], ['family', 'who_family', 'who_family_d']].map(([v, l, d]) => `<button class="tile" style="min-height:92px" data-act="k-who" data-v="${v}" aria-pressed="${K.who === v}">${t(l)}${d ? `<small>${t(d)}</small>` : ''}</button>`).join('')}</div>
      <label class="check mt24"><input type="checkbox" data-change="k-minor" ${P().isMinor ? 'checked' : ''}> <span>${t('minor')}</span></label>${P().isMinor ? `<p class="note mt12" style="max-width:560px">${t('minor_note')}</p>` : ''}
      ${K.profiles.length > 1 ? `<p class="small muted mt16">Profiles in this visit: ${K.profiles.map((p, i) => `<span class="badge ${i === K.pi ? 'b-ink' : ''}">${esc(p.label)}</span>`).join(' ')}</p>` : ''}` }),
    dept: () => ({ foot: false, body: `<div class="k-step">2 / 7</div><h1>${t('dept_h')}</h1><div class="tiles big">${[['WOMEN', 'SR-1003'], ['MEN', 'MK-4002'], ['KIDS', 'KD-6002']].map(([d, pid]) => `<button class="tile dept" data-act="k-dept" data-v="${d}" aria-pressed="${P().dept === d}"><span class="dimg">${FF.garment(FF.prod(pid))}</span>${t(d)}</button>`).join('')}</div>${K.hist.length ? `<button class="btn mt24" style="align-self:flex-start" data-act="k-back">${FF.icon('left')} ${t('back')}</button>` : ''}` }),
    need: () => { const p = P(); const cats = Object.entries(FF.TAX.cats).filter(([, c]) => c.depts.includes(p.dept)); return { skip: !p.cats.length && !p.occasion && !p.budget, body: `<div class="k-step">3 / 7</div><h1>${t('need_h')}</h1>
      <div class="k-sec"><h3>${t('cat_l')}</h3><div class="tiles">${cats.map(([k, c]) => `<button class="tile" data-act="k-cat" data-v="${k}" aria-pressed="${p.cats.includes(k)}">${esc(c.name)}</button>`).join('')}</div></div>
      <div class="k-sec"><h3>${t('occ_l')}</h3><div class="row wrap mt12">${FF.TAX.occasions.map((o) => `<button class="chip" style="min-height:46px;padding:0 18px;font-size:16px" data-act="k-occ" data-v="${o}" aria-pressed="${p.occasion === o}">${t(o)}</button>`).join('')}</div></div>
      <div class="k-sec"><h3>${t('budget_l')}</h3><div class="row wrap mt12">${[1500, 3000, 6000, 12000, 0].map((b) => `<button class="chip" style="min-height:46px;padding:0 18px;font-size:16px" data-act="k-budget" data-v="${b}" aria-pressed="${p.budget === b}">${b ? t('upto', { n: FF.inr(b) }) : t('any')}</button>`).join('')}</div></div>` }; },
    size: () => { const p = P(); const cs = p.cats.length ? p.cats : Object.keys(FF.TAX.cats).filter((k) => FF.TAX.cats[k].depts.includes(p.dept)); const sys = [...new Set(cs.map((c) => FF.TAX.groups[FF.TAX.cats[c].group].size))]; const need = sys.filter((s) => s !== 'FREE'); const lbl = { ALPHA: 'size_top', WAIST: 'size_waist', AGE: 'size_age' };
      return { skip: true, body: `<div class="k-step">4 / 7</div><h1>${t('size_h')}</h1>${sys.includes('FREE') ? `<p class="note n-plain mt16" style="max-width:560px">${t('size_free')}</p>` : ''}
      ${need.map((s) => `<div class="k-sec"><h3>${t(lbl[s])}</h3><div class="tiles sm">${FF.TAX.sizes[s].map((z) => `<button class="tile" data-act="k-size" data-sys="${s}" data-v="${z}" aria-pressed="${p.sizes[s] === z}">${z}</button>`).join('')}</div></div>`).join('')}
      <div class="k-sec"><h3>${t('height_l')}</h3><div class="row wrap mt12">${['petite', 'average', 'tall'].map((h) => `<button class="chip" style="min-height:46px;padding:0 18px;font-size:16px" data-act="k-height" data-v="${h}" aria-pressed="${p.height === h}">${t(h)}</button>`).join('')}</div></div>
      ${need.length ? `<p class="small muted mt24">📏 ${t('size_help')}</p>` : ''}` }; },
    colours: () => { const p = P(); return { skip: !p.likes.length && !p.dislikes.length, body: `<div class="k-step">5 / 7 · ${t('optional')}</div><h1>${t('col_h')}</h1><p class="lead">${t('col_s')}</p><div class="fam">${Object.entries(FF.TAX.families).map(([k, [n, hex]]) => { const s = p.likes.includes(k) ? 'like' : p.dislikes.includes(k) ? 'avoid' : ''; return `<button data-act="k-fam" data-v="${k}" data-s="${s}" aria-label="${esc(n)}${s ? ': ' + s : ''}"><i style="background:${hex}"></i>${esc(n.split(' / ')[0])}${s ? `<span class="tagx">${t(s)}</span>` : ''}</button>`; }).join('')}</div>` }; },
    tone: () => { const p = P(); const canCam = K.consent.camera && K.who !== 'other' && MODE !== 'qr';
      if (!K.toneMode) return { skip: !p.tone, body: `<div class="k-step">6 / 7 · ${t('optional')}</div><h1>${t('tone_h')}</h1><p class="lead">${t('tone_s')}</p><div class="tiles big">${canCam ? `<button class="tile" style="min-height:92px" data-act="k-tonemode" data-v="cam" aria-pressed="false">${FF.icon('camera')} ${t('tone_cam')}<small>${t('tone_cam_d')}</small></button>` : ''}<button class="tile" style="min-height:92px" data-act="k-tonemode" data-v="sw" aria-pressed="false">${t('tone_sw')}<small>${t('tone_sw_d')}</small></button></div>${p.tone ? `<p class="note n-ok mt24" style="max-width:520px">${esc(FF.toneLabel(p))} <button class="link" data-act="k-toneclear">Clear</button></p>` : ''}` };
      if (K.toneMode === 'cam') { const c = K.cam || {}; if (c.stage === 'denied') return { skip: true, body: `<h1>${t('tone_h')}</h1><p class="note mt16" style="max-width:560px">${t('cam_denied')}</p>${swatches(p)}` }; if (c.stage === 'low') return { skip: true, body: `<h1>${t('tone_h')}</h1><p class="note mt16" style="max-width:560px">${t('cam_low')}</p>${swatches(p)}` };
        if (c.stage === 'pick') return { block: !p.tone, body: `<h1>${t('cam_pick')}</h1><div class="monk" style="grid-template-columns:repeat(3,1fr);max-width:340px">${c.near.map((n) => sw(n, p)).join('')}</div><p class="small muted mt16">${p.undertone !== 'unknown' ? `Reading: ${p.undertone} undertone · ${p.contrast} contrast.` : 'Undertone: not sure enough to say, so it is left out.'} <button class="link" data-act="k-tonemode" data-v="sw">None of these</button></p><p class="note n-ok mt16" style="max-width:520px">${FF.icon('lock', 'hide')}🔒 ${t('cam_done')}</p>` };
        return { foot: `<button class="btn" data-act="k-tonemode" data-v="sw">${t('tone_sw')}</button>`, body: `<h1 class="center" style="margin:0 auto">${c.stage === 'read' ? t('cam_read') : t('cam_light')}</h1><div class="cam"><video id="camv" autoplay muted playsinline></video><div class="ring"></div><div class="face"></div></div><div class="meter mt24" style="max-width:280px;margin-inline:auto"><i id="camp" style="width:0%"></i></div><p class="small muted center mt12">${t('tone_cam_d')}</p>`, after: startCam };
      }
      const qs = [['q1', ['gold', 'silver', 'both']], ['q2', ['green', 'blue', 'both']], ['q3', ['tan', 'burn', 'both']]];
      return { skip: !p.tone, block: !p.tone, body: `<div class="k-step">6 / 7 · ${t('optional')}</div><h1>${t('tone_sw')}</h1>${swatches(p)}${p.tone ? qs.map(([qk, opts]) => `<div class="k-sec"><h3>${t(qk)}</h3><div class="row wrap mt12">${opts.map((o) => `<button class="chip" style="min-height:44px;padding:0 18px" data-act="k-quiz" data-q="${qk}" data-v="${o}" aria-pressed="${p.quiz[qk] === o}">${t(o)}</button>`).join('')}</div></div>`).join('') : ''}` }; },
    goals: () => { const p = P(); const list = p.dept === 'MEN' ? ['look_taller', 'streamline_mid', 'broaden_shoulders', 'relaxed'] : ['balance_hips', 'define_waist', 'look_taller', 'streamline_mid', 'relaxed']; return { skip: !p.goals.length, contLabel: t('show_picks'), body: `<div class="k-step">7 / 7 · ${t('optional')}</div><h1>${t('goals_h')}</h1><p class="lead">${t('goals_s')}</p><div class="tiles big">${list.map((g) => `<button class="tile" data-act="k-goal" data-v="${g}" aria-pressed="${p.goals.includes(g)}">${t(g)}</button>`).join('')}</div>` }; },
    results: () => { if (!K.res) { setTimeout(compute, 1100); return { foot: false, body: `<div class="center" style="margin:auto"><div class="spin" style="margin:0 auto 18px;width:34px;height:34px"></div><h1 style="margin:0 auto">${t('res_loading')}</h1><p class="lead" style="margin:8px auto 0">${t('res_loading_s')}</p><div class="heroes" style="width:min(680px,90vw)">${'<div class="skel" style="aspect-ratio:4/6"></div>'.repeat(3)}</div></div>` }; }
      const r = K.res, v = visit(), n = v.shortlist.length;
      const foot = `<button class="btn" data-act="k-edit">${FF.icon('edit')} ${t('edit')}</button><button class="btn btn-p" data-act="k-handoff">${t('to_staff')}${n ? ' · ' + n : ''} ${FF.icon('right')}</button>`;
      if (!r.all.length) return { foot, body: `<div class="k-step">${esc(P().label)}</div><h1>${t('empty_h')}</h1><p class="lead">${t('empty_s')}</p>${r.gap ? `<p class="small muted mt8">${esc(r.gap.reason)}.</p>` : ''}${alts(r)}<div class="row wrap mt24"><button class="btn btn-l" data-act="k-notify">${t('notify')}</button><button class="btn btn-l btn-p" data-act="k-handoff">${t('ask_staff')}</button></div>` };
      return { foot, body: `<div class="row between wrap"><div><div class="k-step">${r.all.length} ${t('instock').toLowerCase()} · ${esc(store().name)}</div><h1>${K.who === 'me' ? t('res_h') : t('res_for', { name: esc(P().label) })}</h1></div><button class="link small" data-act="pop" data-text="${esc(t('how_body'))}">${t('how')} ⓘ</button></div>
        <div class="heroes">${r.heroes.map((i) => card(i, true)).join('')}</div>${r.all.length < 3 ? alts(r) : ''}
        ${r.more.length ? `<div class="k-sec"><h3>${t('res_more')}</h3><div class="more">${r.more.map((i) => card(i)).join('')}</div></div>` : ''}` }; },
    handoff: () => { const v = visit(), off = flags().offline, url = `phone.html?code=${v.code}&lang=${FF.lang}`; const sl = v.shortlist.map(FF.prod);
      return { foot: `${K.who === 'family' ? `<button class="btn" data-act="k-another">${FF.icon('plus')} ${t('another')}</button>` : ''}<span class="grow"></span>${MODE === 'kiosk' ? `<span class="small muted" id="k-left">${t('reset_in', { n: K.left })}</span>` : ''}<button class="btn btn-p" data-act="k-done">${t('done')}</button>`,
        body: `<div class="grid g2 stack" style="align-items:start;gap:28px"><div><div class="k-step">${MODE === 'assisted' ? 'Visit saved' : ''}</div><h1>${MODE === 'assisted' ? 'Picks are ready' : t('hand_h')}</h1><p class="lead">${MODE === 'assisted' ? 'This visit is assigned to you. Open it to see rack locations and mark what was tried.' : t('hand_s')}</p>
          <div class="card mt24 center" style="padding:26px 16px"><div class="bigcode">${v.code}</div><div class="mt12">${off ? `<span class="badge b-warn">${FF.icon('wifioff')} ${t('offline_note')}</span>` : K.notified ? `<span class="badge b-ok">${FF.icon('check')} ${MODE === 'assisted' ? 'Assigned to ' + esc(staffer().name) : t('notified')}</span>` : `<span class="badge">${t('notifying')}</span>`}</div></div>
          ${MODE === 'assisted' ? `<a class="btn btn-b btn-l btn-block mt16" href="app.html#/visit/${v.code}">Open this visit in the staff app ${FF.icon('right')}</a>` : ''}
          <div class="card mt16"><h3>${t('rate_h')}</h3><div class="row mt8">${[1, 2, 3, 4, 5].map((n) => `<button class="x" style="width:46px;height:46px;color:${n <= K.rated ? 'var(--brass)' : 'var(--line2)'}" data-act="k-rate" data-v="${n}" aria-label="${n} of 5">${FF.icon('star').replace('class="ico', `style="width:30px;height:30px;${n <= K.rated ? 'fill:currentColor' : ''}" class="ico`)}</button>`).join('')}${K.rated ? `<span class="small ok">${t('thanks')}</span>` : ''}</div></div></div>
          <div><div class="card"><h3>${t('your_try')} · ${sl.length}</h3>${sl.length ? `<div class="row wrap mt12">${sl.map((p) => `<div style="width:76px"><div class="gimg">${FF.garment(p)}</div><div class="tiny mt4">${esc(p.name)}</div></div>`).join('')}</div>` : `<p class="small muted mt8">Nothing added yet — staff will bring the top picks.</p>`}</div>
          <div class="card mt16 row top gap16">${FF.qr(url, 120)}<div><h3>${t('phone_h')}</h3><p class="small muted mt4">${t('phone_s')}</p><a class="btn btn-s mt12" href="${url}" target="_blank" rel="noopener">${FF.icon('phone')} ${t('open_phone')} (simulate scan)</a></div></div></div></div>`, after: () => { if (!K.notified && !off) setTimeout(() => { K.notified = true; if (K.step === 'handoff') render(); }, 1200); } }; },
  };
  const sw = (n, p) => `<button data-act="k-tone" data-v="${n}" aria-pressed="${p.tone === n}"><i style="background:${FF.TAX.monk[n - 1]}"></i>${t('tone_n', { n })}</button>`;
  const swatches = (p) => `<p class="small muted mt12">${t('swatch_hint')}</p><div class="monk">${FF.TAX.monk.map((_, i) => sw(i + 1, p)).join('')}</div>`;
  const avail = (i) => { const k = i.m.kind; return k === 'exact' ? `${t('instock')} · ${t('yoursize', { size: i.m.size })}` : k === 'free' ? `${t('instock')} · ${t('freesize')}` : k === 'alterable' ? t('alterable', { size: i.m.size }) : k === 'unstitched' ? t('unstitched') + (FF.db.settings.stitching ? ' · ' + t('stitching_av') : '') : k === 'adjacent' ? t('near_size', { size: i.m.size }) : t('instock'); };
  const card = (i, hero) => { const on = visit().shortlist.includes(i.pid), rs = (i.reasons.length ? i.reasons : [{ k: 'avail' }]).slice(0, hero ? 2 : 1); return `<article class="pick">${i.offer ? `<span class="badge b-brass lab">${t('store_pick')}</span>` : ''}<button class="gimg" style="border:0;padding:0;width:100%" data-act="k-detail" data-pid="${i.pid}" aria-label="${t('details')}: ${esc(i.p.name)}">${FF.garment(i.p)}</button><div class="p-b"><h3>${esc(i.p.name)}</h3><div class="row between wrap gap6"><span class="b num">${FF.inr(i.p.price)}</span><span class="tiny ${i.m.kind === 'exact' || i.m.kind === 'free' ? 'ok' : 'warn'} b">${avail(i)}</span></div>${rs.map((r) => `<div class="why">${esc(FF.reasonText(r))}</div>`).join('')}<div class="p-a"><button class="btn ${on ? 'btn-p' : ''}" data-act="k-short" data-pid="${i.pid}" aria-pressed="${on}">${on ? FF.icon('check') + ' ' + t('added') : FF.icon('plus') + ' ' + t('add')}</button></div></div></article>`; };
  const alts = (r) => r.alts.length ? `<div class="k-sec"><h3>${t('alt_h')}</h3><div class="more">${r.alts.map((a) => `<article class="pick"><span class="badge b-warn lab">${a.why === 'near_size' ? t('near_size', { size: a.m.size }) : t(a.why)}</span><div class="gimg" style="border-radius:0">${FF.garment(a.p)}</div><div class="p-b"><h3>${esc(a.p.name)}</h3><span class="b num">${FF.inr(a.p.price)}</span></div></article>`).join('')}</div></div>` : '';

  /* ---------- actions ---------- */
  FF.act('k-begin', (d) => { if (d.v) FF.lang = d.v; go(d.v ? 'consent' : 'lang'); });
  FF.act('k-consent', (d) => { K.consent[d.k] = !K.consent[d.k]; render(); });
  FF.act('k-agree', () => next());
  FF.act('k-decline', () => go('declined'));
  FF.act('k-notice', () => FF.modal({ title: 'Privacy notice · version N-3', body: `<div class="col small"><p><b>${esc(store().name)}</b> decides how your information is used here. FitFirst runs this service on the shop's behalf.</p><p><b>What is kept:</b> your answers (section, size, budget, colours, tone and fit goals if you give them), which pieces you were shown and which you tried. No name or phone number unless you choose to add one.</p><p><b>What is never kept:</b> camera frames. The skin-tone check runs on this device and nothing is uploaded.</p><p><b>How long:</b> ${FF.db.settings.retention.visitDays} days, then deleted automatically. Try-on photos (if you use them on your phone) are deleted within ${FF.db.settings.retention.tryonHours} hours.</p><p><b>Your choices:</b> skip any question, withdraw at any time, or ask us to delete your visit using your code — at the counter or from your phone.</p><p><b>Questions or complaints:</b> ${esc(store().phone)} · privacy@suvarnasilks.example</p><p class="note">Prototype wording. The real notice needs a qualified legal review before use (checklist S0-08).</p></div>`, footer: `<button class="btn btn-p" data-act="close">Close</button>` }));
  FF.act('k-who', (d) => { K.who = d.v; P().label = d.v === 'me' ? 'Me' : d.v === 'other' ? 'Someone else' : 'Person ' + (K.pi + 1); render(); });
  FF.onChange('k-minor', (v, el) => { P().isMinor = el.checked; render(); });
  FF.act('k-dept', (d) => { const p = P(); if (p.dept !== d.v) { p.cats = []; p.sizes = {}; p.goals = []; } p.dept = d.v; if (d.v === 'KIDS') p.isMinor = true; K.res = null; next(); });
  const tog = (arr, v) => { const i = arr.indexOf(v); i < 0 ? arr.push(v) : arr.splice(i, 1); };
  FF.act('k-cat', (d) => { tog(P().cats, d.v); K.res = null; render(); });
  FF.act('k-occ', (d) => { P().occasion = P().occasion === d.v ? null : d.v; K.res = null; render(); });
  FF.act('k-budget', (d) => { P().budget = +d.v; K.res = null; render(); });
  FF.act('k-size', (d) => { const p = P(); p.sizes[d.sys] = p.sizes[d.sys] === d.v ? undefined : d.v; K.res = null; render(); });
  FF.act('k-height', (d) => { P().height = P().height === d.v ? null : d.v; K.res = null; render(); });
  FF.act('k-fam', (d) => { const p = P(); if (p.likes.includes(d.v)) { tog(p.likes, d.v); p.dislikes.push(d.v); } else if (p.dislikes.includes(d.v)) tog(p.dislikes, d.v); else p.likes.push(d.v); K.res = null; render(); });
  FF.act('k-tonemode', (d) => { K.toneMode = d.v; stopCam(); K.cam = d.v === 'cam' ? { stage: flags().camDenied ? 'denied' : 'light' } : null; render(); });
  FF.act('k-tone', (d) => { const p = P(); p.tone = +d.v; if (!p.method || K.toneMode === 'sw') p.method = K.toneMode === 'cam' ? 'camera + confirmed' : 'swatch + quiz'; K.res = null; render(); });
  FF.act('k-toneclear', () => { Object.assign(P(), { tone: null, undertone: 'unknown', contrast: 'unknown', method: null, quiz: {} }); K.res = null; render(); });
  FF.act('k-quiz', (d) => { const p = P(); p.quiz[d.q] = d.v; const a = Object.values(p.quiz); const warm = a.filter((x) => ['gold', 'green', 'tan'].includes(x)).length, cool = a.filter((x) => ['silver', 'blue', 'burn'].includes(x)).length; p.undertone = a.length < 2 ? 'unknown' : warm >= 2 && warm > cool ? 'warm' : cool >= 2 && cool > warm ? 'cool' : 'neutral'; K.res = null; render(); });
  FF.act('k-goal', (d) => { tog(P().goals, d.v); K.res = null; render(); });
  FF.act('k-short', (d) => { const v = visit(); tog(v.shortlist, d.pid); const pk = v.picks.find((x) => x.pid === d.pid); if (pk) pk.state = v.shortlist.includes(d.pid) ? 'shortlisted' : 'shown'; ev(v, 'shortlist', (v.shortlist.includes(d.pid) ? 'Added ' : 'Removed ') + FF.prod(d.pid).name); FF.save(); if (FF.$('.scrim')) FF.closeOverlay(); render(); });
  FF.act('k-detail', (d) => { const i = K.res.all.find((x) => x.pid === d.pid), p = i.p, v = visit(), on = v.shortlist.includes(p.id), s = E.suits(p), g = FF.groupOf(p); const rs = i.reasons.length ? i.reasons : [{ k: 'avail' }];
    FF.modal({ title: esc(p.name), sub: `${FF.inr(p.price)}${p.mrp > p.price ? ` <s class="muted">${FF.inr(p.mrp)}</s>` : ''} · ${avail(i)}`, size: 'wide', body: `<div class="grid g2 stack"><div class="gimg">${FF.garment(p)}</div><div class="col gap16">${i.offer ? `<div><span class="badge b-brass">${t('store_pick')}</span> <span class="small">${esc(i.offer)}</span></div>` : ''}<div><h4>${t('why')}</h4><div class="col gap6 mt8">${rs.slice(0, 3).map((r) => `<div class="row top gap6"><span class="ok b">✓</span><span>${esc(FF.reasonText(r))}</span></div>`).join('')}</div></div><dl class="kv"><dt>Colour</dt><dd><span class="sw" style="background:${p.hex};vertical-align:-3px"></span> ${esc(p.colour)}</dd><dt>Fabric</dt><dd>${FF.cap(p.fabric)}</dd><dt>Work</dt><dd>${FF.cap(p.pattern)}</dd><dt>Good for</dt><dd>${s.occasions.map((o) => t(o)).join(', ')}</dd></dl>${p.unstitched ? `<p class="note">${t('unstitched')}${FF.db.settings.stitching ? ' · ' + t('stitching_av') : ''}</p>` : ''}<p class="tiny muted">Illustration only — the real product photo appears here once the shop has photographed the piece.</p></div></div>`,
      footer: `${g.tryon && !P().isMinor && FF.db.settings.tryon.enabled && !flags().offline ? `<button class="btn" data-act="k-tryqr" data-pid="${p.id}">${FF.icon('spark')} ${t('seeonme')}</button>` : ''}<button class="btn ${on ? '' : 'btn-p'}" data-act="k-short" data-pid="${p.id}">${on ? t('added') + ' ✓' : t('add')}</button>` }); const pk = v.picks.find((x) => x.pid === p.id); if (pk && pk.state === 'shown') { pk.viewed = true; FF.save(); } });
  FF.act('k-tryqr', (d) => { const v = visit(), url = `phone.html?code=${v.code}&try=${d.pid}&lang=${FF.lang}`; FF.closeOverlay(); FF.modal({ title: t('seeonme'), size: 'narrow', body: `<div class="center"><p class="small muted mb16">Try-on photos are always taken on a phone — never on this screen. Scan with your phone camera.</p>${FF.qr(url, 180)}<div class="mt16"><a class="btn btn-p" href="${url}" target="_blank" rel="noopener">${FF.icon('phone')} Open on phone (simulate scan)</a></div><p class="tiny muted mt12">18+ only · separate consent · photo deleted within ${FF.db.settings.retention.tryonHours} h</p></div>` }); });
  FF.act('k-edit', () => { const p = P(); const rows = [['dept', 'Section', FF.TAX.depts[p.dept]], ['need', 'Looking for', [p.cats.map(FF.catName).join(', ') || 'Any type', p.occasion ? t(p.occasion) : 'Any occasion', p.budget ? t('upto', { n: FF.inr(p.budget) }) : 'Any budget'].join(' · ')], ['size', 'Size and height', [Object.values(p.sizes).filter(Boolean).join(', ') || 'Not given', p.height ? FF.cap(p.height) : ''].filter(Boolean).join(' · ')], ['colours', 'Colours', (p.likes.length ? 'Likes ' + p.likes.join(', ') : '') + (p.dislikes.length ? ' · Avoids ' + p.dislikes.join(', ') : '') || 'No preference']]; if (!p.isMinor) rows.push(['tone', 'Skin tone', FF.toneLabel(p)], ['goals', 'Fit goals', p.goals.map((g) => t(g)).join(', ') || 'None']);
    FF.modal({ title: t('edit'), sub: 'Your code stays the same: ' + K.visit, body: `<div class="col">${rows.map(([s, l, v]) => `<div class="row between" style="border-bottom:1px solid var(--line);padding-bottom:10px"><div><div class="tiny muted b">${l}</div><div>${esc(v)}</div></div><button class="btn btn-s" data-act="k-editgo" data-v="${s}">Change</button></div>`).join('')}</div>` }); });
  FF.act('k-editgo', (d) => { FF.closeOverlay(); K.returnTo = d.v === 'dept' ? null : 'results'; go(d.v); });
  FF.act('k-notify', () => FF.modal({ title: t('notify'), size: 'narrow', body: `<form data-submit="k-notify-save" class="col"><p class="small muted">We will send one WhatsApp message when a matching piece arrives. Nothing else.</p>${FF.ui.field('Mobile number', '<input name="phone" type="tel" required pattern="[6-9][0-9]{9}" inputmode="numeric" maxlength="10" placeholder="10-digit number" data-msg="Enter a 10-digit mobile number">')}<label class="check"><input type="checkbox" name="ok" required data-msg="Please tick to agree"> <span class="small">I agree to receive this one message on WhatsApp.</span></label><button class="btn btn-p">Save</button></form>` }));
  FF.act('k-notify-save', (f) => { const g = K.res.gap || {}; FF.db.notify.push({ at: Date.now(), phone: '••••••' + f.phone.slice(-4), want: `${FF.catName(g.cat || 'any')} · ${g.size || ''} · ${g.occasion || ''}` }); FF.save(); FF.closeOverlay(); FF.toast('Saved — we will message you once', 'ok'); });
  FF.act('k-handoff', () => { const v = visit(); if (MODE === 'assisted') { v.status = 'ASSIGNED'; v.staff = staffer().id; ev(v, 'assigned', 'Assisted by ' + staffer().name); K.notified = true; } else { v.status = 'WAITING'; ev(v, 'handoff', 'Handoff code shown' + (flags().offline ? ' (offline)' : '')); } v.waitingSince = Date.now(); FF.save(); K.left = 90; clearInterval(K.timer); if (MODE === 'kiosk') K.timer = setInterval(() => { K.left--; const el = $('#k-left'); if (el) el.textContent = t('reset_in', { n: K.left }); if (K.left <= 0) reset(); }, 1000); go('handoff'); });
  FF.act('k-rate', (d) => { K.rated = +d.v; visit().rating = K.rated; FF.save(); render(); });
  FF.act('k-another', () => { clearInterval(K.timer); K.profiles.push(newProfile('Person ' + (K.profiles.length + 1))); K.pi = K.profiles.length - 1; K.res = null; K.hist = []; K.step = 'who'; K.who = 'family'; render(); });
  FF.act('k-done', () => reset());

  /* ---------- engine run + visit record ---------- */
  function compute() {
    if (K.step !== 'results') return; const p = P(); let v = visit();
    if (!v) { const code = FF.newCode(); v = { id: FF.uid('v'), code, at: Date.now(), channel: MODE === 'qr' ? 'QR' : MODE.toUpperCase(), status: 'BROWSING', staff: null, holdout: FF.hash(code) % 100 < FF.db.settings.holdout, lang: FF.lang, profiles: K.profiles, picks: [], shortlist: [], events: [], rating: null, tryons: 0, tryLimit: FF.db.settings.tryon.perVisit, consent: Object.assign({}, K.consent) }; FF.db.visits.push(v); K.visit = code; ev(v, 'start', 'Consultation started (' + v.channel.toLowerCase() + ')'); ['personal', 'camera'].forEach((k) => FF.db.consents.unshift({ at: Date.now(), code, purpose: k === 'personal' ? 'Personalisation' : 'On-device camera', granted: !!K.consent[k], notice: 'N-3', lang: FF.lang, method: 'On-screen toggle' })); }
    v.profiles = K.profiles; v.lang = FF.lang;
    const r = (K.res = E.recommend(p, { holdout: v.holdout }));
    v.picks = v.picks.filter((x) => x.profile !== K.pi).concat(r.all.map((i) => ({ pid: i.pid, rank: i.rank, profile: K.pi, state: v.shortlist.includes(i.pid) ? 'shortlisted' : 'shown', boosted: i.boosted, size: i.m.size, sizeKind: i.m.kind, reasons: i.reasons.slice(0, 2).map((x) => ({ k: x.k, v: x.v })), offer: i.offer, age: i.age, S: Math.round(i.S * 100) / 100, talk: E.talk(i) })));
    v.shortlist = v.shortlist.filter((id) => v.picks.some((x) => x.pid === id));
    r.all.forEach((i) => { i.p.imp7 = (i.p.imp7 || 0) + 1; });
    ev(v, 'run', `Recommendations for ${p.label}: ${r.all.length} shown${v.holdout ? ' (holdout — no clearance boost)' : ''}`);
    if (r.gap) { const g = FF.db.gaps.find((x) => x.cat === r.gap.cat && x.size === r.gap.size && x.occasion === r.gap.occasion); if (g) g.count++; else FF.db.gaps.unshift({ id: FF.uid('g'), cat: r.gap.cat, size: r.gap.size, budget: r.gap.budget, occasion: r.gap.occasion, palette: r.gap.palette, count: 1, had: r.gap.had, status: 'open', fresh: true }); }
    FF.save(); render();
  }

  /* ---------- camera (simulated measurement; optional live preview) ---------- */
  let camStream = null, camT = null;
  function stopCam() { clearTimeout(camT); if (camStream) { camStream.getTracks().forEach((x) => x.stop()); camStream = null; } }
  function startCam() {
    const c = K.cam; if (!c || c.running) return; c.running = true; const vid = $('#camv');
    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } }).then((s) => { if (K.toneMode !== 'cam' || !$('#camv')) { s.getTracks().forEach((x) => x.stop()); return; } camStream = s; $('#camv').srcObject = s; }).catch(() => { /* preview unavailable: the placeholder ring is shown instead */ });
    let f = 0; const tick = () => { if (K.toneMode !== 'cam') return; f++; const bar = $('#camp'); if (bar) bar.style.width = Math.min(100, (f / 28) * 100) + '%'; if (f === 8) { c.stage = 'read'; const h = $('.k-main h1'); if (h) h.textContent = t('cam_read'); } if (f >= 28) { stopCam(); const p = P(); if (flags().lowLight) c.stage = 'low'; else { c.stage = 'pick'; c.near = [4, 5, 6]; p.undertone = 'warm'; p.contrast = 'medium'; p.method = 'camera + confirmed'; } c.running = false; return render(); } camT = setTimeout(tick, 110); }; camT = setTimeout(tick, 110);
  }

  /* ---------- idle protection (kiosk only) ---------- */
  ['pointerdown', 'keydown', 'touchstart'].forEach((e) => document.addEventListener(e, () => { last = Date.now(); }, true));
  FF.act('k-keep', () => { idleLeft = 0; last = Date.now(); FF.closeOverlay(); });
  setInterval(() => { if (MODE !== 'kiosk' || ['attract', 'handoff', 'declined'].includes(K.step)) return; if (idleLeft > 0) { idleLeft--; const el = $('#idle-n'); if (el) el.textContent = t('idle_b', { n: idleLeft }); if (idleLeft === 0) reset(); return; } if (Date.now() - last > 60000) { idleLeft = 15; FF.modal({ title: t('idle_h'), size: 'narrow', sticky: true, body: `<p id="idle-n">${t('idle_b', { n: 15 })}</p>`, footer: `<button class="btn" data-act="k-restart-now">${t('startover')}</button><button class="btn btn-p" data-act="k-keep">${t('keep')}</button>` }); } }, 1000);
  FF.act('k-restart-now', () => { idleLeft = 0; reset(); });
  FF.onSync = () => { if (K.step === 'attract') render(); };
  if (q.get('lang')) FF.lang = q.get('lang');
  render();
})();
